use std :: cmp :: Ordering ; use std :: collections :: HashMap ; use forge_domain :: { Node , NodeId } ; use forge_domain :: { Node , NodeData } ; use pretty_assertions :: assert_eq ; use super :: * ; # [doc = " Deduplicates code search results across multiple queries."] # [doc = ""] # [doc = " Each node appears only once across all query results, kept in the query"] # [doc = " where it has the highest score according to the `BestScore` ordering."] # [doc = ""] # [doc = " # Arguments"] # [doc = " * `results` - Vector of search results per query (will be modified in place)"] # [doc = ""] # [doc = " # Errors"] # [doc = " Returns an error if node IDs cannot be extracted from results."] pub fn deduplicate_results (results : & mut [Vec < Node >]) { let mut best_scores : HashMap < NodeId , Score > = HashMap :: new () ; for (query_idx , query_results) in results . iter () . enumerate () { for result in query_results { let current_score = Score :: new (query_idx , result) ; match best_scores . entry (result . node_id . clone ()) { std :: collections :: hash_map :: Entry :: Occupied (mut entry) => { if current_score > * entry . get () { entry . insert (current_score) ; } } std :: collections :: hash_map :: Entry :: Vacant (entry) => { entry . insert (current_score) ; } } } } for (query_idx , query_results) in results . iter_mut () . enumerate () { query_results . retain (| result | { best_scores . get (& result . node_id) . is_none_or (| best | best . query_idx == query_idx) }) ; } }